  assert.equal(LIVE_LIMITS.timeoutMs, 15000);
  console.log(JSON.stringify({ tier: 'MOCK_ONLY', technicalPromptBudgetBytes: budget, byteBudget: LIVE_LIMITS.inputTokens }));
})

